import com.wolinski.shop.money.Money;
import com.wolinski.shop.platform.ShopProblem;
import java.util.regex.Pattern;

/** A discount rate in whole basis points (1 bp = 0.01%). Parsed from admin-form text such as "12.5". */
record DiscountRate(long basisPoints) {

    private static final Pattern FORMAT = Pattern.compile("\\d{1,3}(\\.\\d{1,2})?");
    private static final long MAX_BASIS_POINTS = 10_000;

    static DiscountRate parse(String percent) {
        if (null == percent || false == FORMAT.matcher(percent).matches()) {
            throw new ShopProblem("invalid-percent", "Not a percentage: " + percent);
        }
        int dot = percent.indexOf('.');
        String whole = dot < 0 ? percent : percent.substring(0, dot);
        String fraction = dot < 0 ? "" : percent.substring(dot + 1);
        long bp = Long.parseLong(whole) * 100 + (fraction.isEmpty() ? 0 : Long.parseLong(fraction) * (fraction.length() == 1 ? 10 : 1));
        if (bp > MAX_BASIS_POINTS) {
            throw new ShopProblem("invalid-percent", "Percentage above 100: " + percent);
        }
        return new DiscountRate(bp);
    }

    /** The discount on the given amount, rounded half up to a whole minor unit. */
    Money of(Money amount) {
        long discount = Math.addExact(Math.multiplyExact(amount.minorUnits(), basisPoints), MAX_BASIS_POINTS / 2) / MAX_BASIS_POINTS;
        return new Money(discount, amount.currency());
    }
}
}

