import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.platform.ShopProblem;
import org.junit.jupiter.api.Test;

class DiscountRateTest {

    @Test
    void halfAMinorUnitRoundsUp() {
        // 0.5% of 1.00 PLN is 0.005 PLN, which rounds half up to 0.01 PLN
        assertEquals(Money.pln(1), DiscountRate.parse("0.5").of(Money.pln(100)));
    }

    @Test
    void discountIsRoundedHalfUp() {
        assertEquals(Money.pln(63), DiscountRate.parse("12.5").of(Money.pln(500)));
        assertEquals(Money.pln(62), DiscountRate.parse("12.5").of(Money.pln(499)));
    }

    @Test
    void parsesWholeAndFractionalPercents() {
        assertEquals(new DiscountRate(1250), DiscountRate.parse("12.5"));
        assertEquals(new DiscountRate(1250), DiscountRate.parse("12.50"));
        assertEquals(new DiscountRate(1205), DiscountRate.parse("12.05"));
        assertEquals(new DiscountRate(1200), DiscountRate.parse("12"));
        assertEquals(new DiscountRate(10000), DiscountRate.parse("100"));
    }

    @Test
    void rejectsMalformedOrOutOfRangePercents() {
        for (String bad : new String[] {"", " 12", "12,5", "-1", "+5", "1e1", "12.555", "100.01", "101", "abc", "1000", null}) {
            ShopProblem problem = assertThrows(ShopProblem.class, () -> DiscountRate.parse(bad), bad);
            assertEquals("invalid-percent", problem.code());
        }
    }
}
}

